    sensor.body_exited.connect(_exited)
func _entered(actor: Node2D) -> void:
    occupants[actor.get_instance_id()] = weakref(actor)
    approach_requested.emit(actor)
func _exited(actor: Node2D) -> void:
    occupants.erase(actor.get_instance_id())

func _on_body_entered(body: Node2D) -> void:
    if claimed or not body is CharacterBody2D:
        return
    claimed = true # synchronous guard before the deferred change
    set_deferred("monitoring", false)
    collected.emit(value)

func _entered(actor: Node2D) -> void:
    occupants[actor.get_instance_id()] = weakref(actor)
func _exited(actor: Node2D) -> void:
    occupants.erase(actor.get_instance_id())
    for id in occupants.keys():
        if occupants[id].get_ref() == null:
            occupants.erase(id)
    if not occupants.is_empty():
        return false

func on_top(body: Node2D) -> void:
    if dead or not body is CharacterBody2D or body.velocity.y <= 0:
        return
    dead = true
    if body.has_method("bounce"):
        body.bounce()
    $Top.set_deferred("monitoring", false)
    $Side.set_deferred("monitoring", false)
    set_deferred("collision_layer", 0)
    defeated.emit()

func open() -> void:
    if locked or is_open:
        return
    is_open = true
    solid.set_deferred("disabled", true)
